import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_none_counts_in_denominator():
    assert conversion_rate([
        {"converted": True}, {"converted": None}, {"converted": False}
    ]) == 1 / 3
    assert conversion_rate([]) == 0.0
    assert conversion_rate([{"converted": None}]) == 0.0


def test_pooled_rate_weights_sessions_and_handles_empty_groups():
    groups = {
        "small": [{"converted": True}],
        "large": [{"converted": False}, {"converted": None}, {"converted": False}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({}) == 0.0
    assert pooled_conversion_rate({"empty": []}) == 0.0


def test_conversions_in_window():
    counts = [1, 2, 3, 4]
    assert conversions_in_window(counts, 0) == 0
    assert conversions_in_window(counts, 1) == 4
    assert conversions_in_window(counts, 2) == 7
    assert conversions_in_window(counts, 4) == 10
    assert conversions_in_window(counts, 9) == 10
    assert conversions_in_window([], 3) == 0


def test_parse_session_log_flags_whitespace_and_skipped_lines():
    assert parse_session_log([
        "\n", "  # comment,with,commas", "   ",
        " a , 2 , 1 ", "b, -1, 0", "c, 0,  ",
    ]) == [
        {"id": "a", "day": 2, "converted": True},
        {"id": "b", "day": -1, "converted": False},
        {"id": "c", "day": 0, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,no,1", "a,1,yes"])
def test_parse_session_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_session_log([" ", " # comment", bad_line])


def test_dedupe_sessions_keeps_last_duplicate_and_sorts_by_day_and_id():
    events = [
        {"id": "a", "day": 1, "converted": True},
        {"id": "b", "day": 2, "converted": True},
        {"id": "a", "day": 2, "converted": False},
        {"id": "c", "day": 1, "converted": None},
    ]
    assert dedupe_sessions(events) == [events[3], events[2], events[1]]
    assert dedupe_sessions([]) == []


def test_daily_conversion_counts_range_and_gaps():
    events = [
        {"day": 0, "converted": True},
        {"day": 1, "converted": True},
        {"day": 1, "converted": True},
        {"day": 2, "converted": None},
        {"day": 3, "converted": False},
        {"day": 4, "converted": True},
    ]
    assert daily_conversion_counts(events, 1, 3) == [2, 0, 0]
    assert daily_conversion_counts([], 1, 3) == [0, 0, 0]
    assert daily_conversion_counts(events, 3, 1) == []


def test_campaign_summary_pooled_recent_and_nonempty_groups():
    groups = {
        "a": [{"day": 1, "converted": True}],
        "b": [{"day": 3, "converted": True}, {"day": 6, "converted": False}],
        "empty": [],
    }
    assert campaign_summary(groups, 3) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 4)["recent"] == 1
    assert campaign_summary(groups, 0)["recent"] == 0
    assert campaign_summary({"empty": []}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"converted": True}],
        "empty": [],
        "b": [{"converted": False}],
        "a": [{"converted": True}],
    }
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 10) == ["a", "z", "b"]
    assert top_converting_groups(groups, 0) == []


def test_conversion_rate_by_group_includes_empty_and_sorts_keys():
    groups = {"z": [], "b": [{"converted": None}], "a": [{"converted": True}]}
    result = conversion_rate_by_group(groups)
    assert result == {"a": 1.0, "b": 0.0, "z": None}
    assert list(result) == ["a", "b", "z"]


def test_longest_conversion_streak_resets_on_nonpositive_counts():
    assert longest_conversion_streak([1, 2, 0, 3, -1, 4, 5, 6]) == 3
    assert longest_conversion_streak([0, -1, 0]) == 0
    assert longest_conversion_streak([]) == 0

